-- Weekly digest editions, generated by the poller (Friday afternoons).
-- `content` stores only ids + editorial copy (summaries, ledes, editor's
-- note); the web app re-joins live bookmark data at render time so author
-- info, media, and metrics never go stale inside an edition.
create table digests (
  id            int generated always as identity primary key,  -- doubles as the issue number
  period_start  timestamptz not null,
  period_end    timestamptz not null,
  generated_at  timestamptz not null default now(),
  content       jsonb not null
);

create index digests_period_end on digests (period_end desc);

grant select on digests to bookmarks_ro;
